<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ $aset->exists ? 'Edit' : 'Tambah' }} Aset</title><style>body{font-family:Arial;background:#f5f7fa;margin:0}.wrap{max-width:1000px;margin:30px auto;padding:20px;background:#fff;border-radius:10px}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:15px}.field{display:flex;flex-direction:column;gap:6px}.field input,.field select,.field textarea{padding:10px;border:1px solid #ccd3db;border-radius:6px}.full{grid-column:1/-1}.actions{margin-top:20px;display:flex;gap:10px}.btn{padding:10px 15px;border:0;border-radius:6px;text-decoration:none;cursor:pointer}.primary{background:#123b63;color:#fff}.secondary{background:#ddd;color:#222}.errors{background:#fee4e2;padding:12px;margin-bottom:15px}</style></head><body><div class="wrap"><h1>{{ $aset->exists ? 'Edit' : 'Tambah' }} Inventarisasi Aset</h1>@if($errors->any())<div class="errors"><ul>@foreach($errors->all() as $error)<li>{{ $error }}</li>@endforeach</ul></div>@endif<form method="post" action="{{ $aset->exists ? route('aset.update',$aset) : route('aset.store') }}">@csrf @if($aset->exists) @method('PUT') @endif<div class="grid">@php $fields=[['kode_barang','Kode Barang'],['nama_barang','Nama Barang'],['kib','KIB'],['kategori','Kategori Aset'],['merk_type','Merk/Type'],['nomor_register','Nomor Register'],['tahun_perolehan','Tahun Perolehan'],['sumber_dana','Sumber Dana'],['jumlah','Jumlah'],['satuan','Satuan'],['harga_perolehan','Harga Perolehan'],['lokasi','Lokasi'],['pengguna_barang','Pengguna Barang'],['penanggung_jawab','Penanggung Jawab'],['nomor_dokumen','Nomor Dokumen']]; @endphp @foreach($fields as [$name,$label])<div class="field"><label>{{ $label }}</label><input name="{{ $name }}" value="{{ old($name,$aset->$name) }}" type="{{ in_array($name,['tahun_perolehan','jumlah','harga_perolehan'])?'number':'text' }}" {{ in_array($name,['kode_barang','nama_barang','jumlah'])?'required':'' }}></div>@endforeach<div class="field"><label>Kondisi</label><select name="kondisi">@foreach(['Baik','Rusak Ringan','Rusak Berat'] as $v)<option {{ old('kondisi',$aset->kondisi)===$v?'selected':'' }}>{{ $v }}</option>@endforeach</select></div><div class="field full"><label>Keterangan</label><textarea name="keterangan" rows="4">{{ old('keterangan',$aset->keterangan) }}</textarea></div></div><div class="actions"><a class="btn secondary" href="{{ route('aset.index') }}">Kembali</a><button class="btn primary">Simpan</button></div></form></div></body></html>
